    timer := time.NewTimer(delay)
    select {
    case <-ctx.Done(): if !timer.Stop() { select { case <-timer.C: default: } }; return
    case <-timer.C:
    }
   }
   if ctx.Err() != nil { return }
   if err := r.Report(ctx); err != nil { r.logger.WithError(err).Warn("reporting anonymous telemetry") }
   timer := time.NewTimer(interval)
   select {
